arguments.command:
$path = "X:\code\copilot-worktrees\P06\cirvine-msft-silver-spoon\assets\due.txt"
$bytes = [System.IO.File]::ReadAllBytes($path)
$content = [System.IO.File]::ReadAllText($path)

# Count CR (byte 13) and LF (byte 10)
$crCount = ($bytes | Where-Object { $_ -eq 13 }).Count
$lfCount = ($bytes | Where-Object { $_ -eq 10 }).Count

Write-Host "CR (byte 13) count: $crCount"
Write-Host "LF (byte 10) count: $lfCount"
Write-Host ""

# Check each line for disallowed characters
$allowedChars = @(' ', '+', '|', '/', '\', '_', '*', '.', '#', '(', ')', ':', '=', '-', "`n")
$charRanges = 'A'..'Z' + '0'..'9'
$allAllowed = $allowedChars + $charRanges

$lines = $content.Split("`n")
$contentLines = $lines | Where-Object { $_ -ne "" }

Write-Host "Checking line content for allowed characters only..."
$validChars = $true
foreach ($line in $contentLines) {
    foreach ($char in $line.ToCharArray()) {
        if ($char -notin $allAllowed) {
            Write-Host "✗ Found disallowed char: '$char' (ASCII $([int][char]$char))"
            $validChars = $false
        }
    }
}

if ($validChars) {
    Write-Host "✓ All characters are allowed"
}

